import{_ as t,c as a,o,ah as p,ao as s,ap as i}from"./chunks/framework.Dq2_gudl.js";const u=JSON.parse('{"title":"Увижу ли я его снова? Что Библия говорит о животных и небе","description":"Самый глубокий вопрос после потери питомца: будет ли он на небе? Что нам дают Римлянам, Исаия и Откровение.","frontmatter":{"title":"Увижу ли я его снова? Что Библия говорит о животных и небе","description":"Самый глубокий вопрос после потери питомца: будет ли он на небе? Что нам дают Римлянам, Исаия и Откровение."},"headers":[],"relativePath":"ru/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"ru/pets-in-heaven/will-i-see-my-pet-again.md"}'),l={name:"ru/pets-in-heaven/will-i-see-my-pet-again.md"};function n(r,e,h,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[p('<div class="pl-quote"><p>«Я знаю, что буду на небе. Я только хочу знать — он будет там меня ждать?»</p><p class="pl-quote-soft">Это вопрос, который люди, потерявшие друга-животное, задают чаще всего — и произносят вслух труднее всего.</p></div><section class="pl-section"><h2>Сначала честное слово</h2><p>В Библии нет стиха, который говорил бы: «каждый питомец воссоединится с хозяином на небе». Кто утверждает это слишком уверенно — говорит больше, чем говорит Писание.</p><p>Но не отчаивайтесь из-за этого. Картина, которую рисует Библия, гораздо шире, чем мы думаем: Божье искупление никогда не было только «вытащить несколько человеческих душ из обломков» — это <strong>обновление всего творения</strong>. И животные в этой картине от начала до конца.</p></section><section class="pl-section"><h2>1. Само творение ждёт вместе с нами</h2><blockquote><p><strong>К Римлянам 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>Павел говорит здесь поразительную вещь: не только люди стонут и ждут. <em>Само творение</em> стонет и ждёт искупления. Животные — не декорация, оставленная за пределами спасения: они смотрят на тот же конец, что и мы.</p><p>Когда вы говорите: «он был таким добрым — он не должен был просто исчезнуть», вы чувствуете именно то, что чувствует творение. Писание говорит, что эта боль будет услышана.</p></section><section class="pl-section"><h2>2. В мире, который создаст Бог, есть животные</h2><blockquote><p><strong>Исаия 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>Будущее, которое увидел Исаия, — не мир только из света и облаков. Он увидел волков, ягнят, барсов, козлят, телят и львов — мир, где никто не вредит и все лежат в безопасности.</p><p>Если бы Божий замысел о животных был «они только для этой жизни, а потом всё», Он не дал бы им места в Своих обещаниях. Он дал.</p><p>А описывая новое небо и новую землю, Откровение говорит:</p><blockquote><p><strong>Откровение 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>«Смерти больше не будет» — это объявление обо всём творении. Смерть, через которую прошёл ваш питомец, — одна из тех вещей, что будут отменены.</p></section><section class="pl-section"><h2>3. Насколько же мы можем надеяться?</h2><p>Мы можем надеяться, потому что Бог не оставляет того, что создал. Мы можем надеяться, потому что воскресение Христа — первый плод нового творения, а Писание говорит, что его охват — «всё». Мы можем надеяться, потому что Бог, создавший животных и радовавшийся им, не перестанет вдруг о них заботиться.</p><p>А «будет ли это тот же самый?» и «помнит ли он меня?» — деталей Библия не даёт. Она даёт нам Бога, которому можно доверять, а детали — в Его руках. Это молчание не для того, чтобы мучить нас; это приглашение отдать то, чего мы не знаем, в добрые руки.</p><p class="pl-quote-soft">Если хотите, можете помолиться так:</p></section><div class="pl-quote"><p>«Господи, я не знаю деталей о небе, но верю, что Ты благ.<br>Ты создал его. Ты хранил каждый день его жизни. Ты видишь мои слёзы сейчас.<br>Я вверяю его в Твои руки — как вверяю себя.<br>Если в Твоих обещаниях есть для него место — благодарю Тебя.<br>А если о нём нужно заботиться, я рад, что это Ты. Аминь.»</p></div><section class="pl-section"><h2>Для особенно трудного дня</h2><p>Псалмопевец писал: «Господи, Ты хранишь человека и животное» (Псалом 36:6). Короткая строка, но это один из редких стихов, где животные прямо поставлены внутри Божьей хранящей заботы.</p><p>Ваш питомец принадлежит Богу, Который хранит «человека и животное». Возможно, сегодня нужно не исчерпывающее объяснение, а только это: он в Божьих руках, и Бог благ.</p><p><a href="/ru/pets-in-heaven/">← Вернуться к Pets in Heaven</a> ｜ Далее: <a href="/ru/pets-in-heaven/not-one-sparrow-forgotten">Ни один воробей не забыт</a></p></section><div class="pl-cta"><h2>Напишите его имя.</h2><p>Напишите его имя, любимое место, фразу, которую не успели сказать. PetLoss — приватное пространство: без загрузок, без спешки, помогает собрать это понемногу.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Скачать в App Store</a></div><div class="pl-bible"><h3>Пусть слово Писания остаётся с вами</h3><p>Все стихи в этой статье — из Библии. С приложением Rainbow Bible вы можете читать Писание в любое время и настроить виджет со стихом дня — небольшой свет для дней, когда вы скучаете.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Виджет Rainbow Bible со стихом 2 Тимофею 2:13" loading="lazy"><figcaption>Стих дня на главном экране</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible — тема «Питомцы на небесах» со стихом Матфея 10:29-31" loading="lazy"><figcaption>Читайте Писание в теме «Питомцы на небесах»</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Скачать Rainbow Bible в App Store</a></div>',9)])])}const m=t(l,[["render",n]]);export{u as __pageData,m as default};
